{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("c", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session(str(i), 2, False) for i in range(3)],
              "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (5, 9)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_fields_and_skipped_lines():
    lines = ["  # header, not a record", "", " \t ", " a , 2 , 1 ",
             " b, -1, 0 ", " c, 3,  "]
    assert parse_session_log(lines) == [session("a", 2, True),
                                        session("b", -1, False),
                                        session("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# heading", "  ", "ok,1,1", bad_line])


def test_dedupe_sessions_last_duplicate_wins_then_sorts():
    first = session("a", 1, True)
    replacement = session("a", 3, False)
    events = [first, session("z", 3, True), session("b", 2, True), replacement,
              session("c", 3, None)]
    assert dedupe_sessions(events) == [events[2], replacement, events[4], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [session("a", 0, True), session("b", 1, True),
              session("c", 1, True), session("d", 2, None),
              session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts(events, 2, 2) == [0]
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_pooled_rate_calendar_days_and_nonempty_groups():
    groups = {"empty": [], "a": [session("a", 1, True)],
              "b": [session("b", 4, True), session("c", 4, False)]}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [session("b", 1, False)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_conversion_streak_only_counts_positive_values():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 3, 4, 5]) == 3
    assert longest_conversion_streak([-1, 0]) == 0
    assert longest_conversion_streak([]) == 0
